import numpy as np

# ALGORITHM_ANALYSIS_NOTE_BEGIN
# Summary: This algorithm is a compact, randomized approach to black-box optimization.
# Search state: The search state is represented by a single candidate solution vector.
# Candidate generation: New candidate solutions are generated by applying Gaussian
#                       perturbations to the current best solution.
# Selection and replacement: The new candidate replaces the current best solution
#                            if it has a lower objective function value.
# Adaptation: The standard deviation of the Gaussian perturbations is adapted
#             based on the progress of the search, to balance exploration and exploitation.
# Exploration mechanisms: Gaussian perturbations provide a balance of local and global search.
# Exploitation mechanisms: The search focuses on improving the current best solution.
# Boundary handling: Candidate solutions that violate the search space bounds are
#                    reflected back into the feasible region.
# Budget strategy: The algorithm uses the full evaluation budget, without exceeding it.
# Closest known influences: This algorithm is inspired by classic gradient-free optimization
#                           methods, such as the Nelder-Mead simplex method.
# Novelty or unusual aspects: The adaptive standard deviation and the boundary handling
#                             are relatively simple but effective mechanisms.
# Failure modes: The algorithm may struggle in high-dimensional problems or problems
#                with many local minima, as it relies on a single candidate solution.
# ALGORITHM_ANALYSIS_NOTE_END

class Algorithm:
    def __init__(self, budget, dim):
        self.budget = budget
        self.dim = dim
        self.x = np.zeros(self.dim)
        self.f = np.inf
        self.std = 1.0

    def __call__(self, func):
        lb, ub = func.bounds.lb, func.bounds.ub
        self.budget_remaining = self.budget

        while self.budget_remaining > 0:
            # Generate new candidate solution
            candidate = self.x + self.std * np.random.normal(size=self.dim)

            # Clip candidate to search space bounds
            candidate = np.clip(candidate, lb, ub)

            # Evaluate candidate
            y = func(candidate)
            self.budget_remaining -= 1

            # Update best solution
            if y < self.f:
                self.x = candidate
                self.f = y

            # Adapt standard deviation
            self.std = max(0.1, self.std * np.exp(-0.01 * self.budget_remaining / self.budget))

        return self.x, self.f
